 4	final class ActivitySelector {
 5	    private static final Comparator<Activity> BY_FINISH_TIME =
 6	        Comparator.comparingInt(Activity::getFinishTime);
 7	
 8	    private ActivitySelector() {
 9	    }
10	
11	    static int maxCompatibleActivities(int[] startTimes, int[] finishTimes) {
12	        validateSchedule(startTimes, finishTimes);
13	
14	        if (startTimes.length == 0) {
15	            return 0;
16	        }
17	
18	        Activity[] activities = buildActivities(startTimes, finishTimes);
19	        Arrays.sort(activities, BY_FINISH_TIME);
