24	    private static void validateSchedule(int[] startTimes, int[] finishTimes) {
25	        if (startTimes == null || finishTimes == null) {
26	            throw new IllegalArgumentException("Start and finish times must not be null.");
27	        }
28	
29	        if (startTimes.length != finishTimes.length) {
30	            throw new IllegalArgumentException("Start and finish times must have the same length.");
31	        }
32	    }
33	
34	    private static Activity[] buildActivities(int[] startTimes, int[] finishTimes) {
35	        Activity[] activities = new Activity[startTimes.length];
36	
37	        for (int i = 0; i < startTimes.length; i++) {
38	            activities[i] = new Activity(startTimes[i], finishTimes[i]);
39	        }
40	
41	        return activities;
42	    }
43	
44	    private static int countCompatibleActivities(Activity[] activities) {
45	        int selectedCount = 1;
46	        Activity lastSelected = activities[0];
47	
48	        for (int i = 1; i < activities.length; i++) {
49	            Activity candidate = activities[i];
50	
51	            if (candidate.getStartTime() > lastSelected.getFinishTime()) {
52	                selectedCount++;
53	                lastSelected = candidate;
54	            }
55	        }
56	
57	        return selectedCount;
58	    }
59	}

